/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Types: AvcConfigurationOptions, ClipOptions
 *   Functions: u32, u16, box, avcConfiguration, sampleEntry, clip, patchBoxSize
 *   Constants: ffmpeg, ffmpegAvailable
 * Tests
 *   - the container walk accepts one progressive H.264 video track and reports its facts
 *   - the sample entry accepts browser H.264 profiles, padding, non-square pixels, and ordinary sibling boxes
 *   - the sample entry rejects a coded size or H.264 configuration a small track header could hide
 *   - the container walk rejects every profile outside the bounded, muted, progressive clip
 *   - file validation checks size, type, and exact bytes before decoding, and hashes the accepted clip
 *   - a real H.264 clip decodes completely, and a corrupted one is rejected
 *   - real High-profile clips at the size limit decode, and a larger stream behind small headers does not
 * @end-catalog */

import assert from 'node:assert/strict';
import { execFileSync, spawnSync } from 'node:child_process';
import { mkdtempSync, readFileSync, rmSync, statSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import path from 'node:path';
import test from 'node:test';

import {
    InvalidMotionPreviewError,
    inspectMotionPreviewContainer,
    validateMotionPreviewFile
} from '../../src/services/media/motionPreviewValidation';
import { UndecodableMotionPreviewError } from '../../src/services/media/motionPreviewDecoder';

const u32 = (value: number) => {
    const buffer = Buffer.alloc(4);
    buffer.writeUInt32BE(value);
    return buffer;
};

const u16 = (value: number) => {
    const buffer = Buffer.alloc(2);
    buffer.writeUInt16BE(value);
    return buffer;
};

const box = (type: string, ...children: Buffer[]) => {
    const payload = Buffer.concat(children);
    return Buffer.concat([u32(8 + payload.length), Buffer.from(type, 'latin1'), payload]);
};

interface AvcConfigurationOptions {
    version?: number;
    profile?: number;
    spsProfile?: number;
    spsHeader?: number;
    lengthSizeMinusOne?: number;
    spsCount?: number;
    /** Optional High-profile trailer: chroma_format, bit_depth_luma_minus8, bit_depth_chroma_minus8. */
    highExtension?: [number, number, number];
}

/** An AVCDecoderConfigurationRecord with SPS and PPS NALs; only its header and SPS profile matter here. */
const avcConfiguration = ({
    version = 1, profile = 100, spsProfile = profile, spsHeader = 0x67, lengthSizeMinusOne = 3, spsCount = 1,
    highExtension
}: AvcConfigurationOptions = {}) => {
    const sps = Buffer.from([spsHeader, spsProfile, 0x00, 0x1e, 0xac, 0xd9]);
    const pps = Buffer.from([0x68, 0xeb, 0xe3, 0xcb]);
    return Buffer.concat([
        Buffer.from([version, profile, 0x00, 0x1e, 0xfc | lengthSizeMinusOne, 0xe0 | spsCount]),
        ...Array.from({ length: spsCount }, () => Buffer.concat([u16(sps.length), sps])),
        Buffer.from([1]), u16(pps.length), pps,
        ...(highExtension ? [Buffer.from([
            0xfc | highExtension[0], 0xf8 | highExtension[1], 0xf8 | highExtension[2], 0x00
        ])] : [])
    ]);
};

/** A VisualSampleEntry: 78 fixed bytes with the coded size at offset 24, then its child boxes. */
const sampleEntry = (codec: string, codedWidth: number, codedHeight: number, ...children: Buffer[]) => {
    const fields = Buffer.alloc(78);
    fields.writeUInt16BE(1, 6);
    fields.writeUInt16BE(codedWidth, 24);
    fields.writeUInt16BE(codedHeight, 26);
    fields.writeUInt32BE(0x00480000, 28);
    fields.writeUInt32BE(0x00480000, 32);
    fields.writeUInt16BE(1, 40);
    fields.writeUInt16BE(0x18, 74);
    fields.writeInt16BE(-1, 76);
    return box(codec, fields, ...children);
};

interface ClipOptions {
    brand?: string;
    timescale?: number;
    duration?: number;
    width?: number;
    height?: number;
    codedWidth?: number;
    codedHeight?: number;
    handler?: string;
    codec?: string;
    /** The avcC payload; null omits the box. */
    avcC?: Buffer | null;
    entryChildren?: Buffer[];
    /** Replaces the whole stsd entry list. */
    entries?: Buffer;
    tracks?: number;
    order?: 'progressive' | 'moov-last';
    extraTop?: Buffer[];
    extraMovie?: Buffer[];
}

/** Builds a structurally complete MP4 box tree; its sample data is never decoded here. */
const clip = ({
    brand = 'isom', timescale = 1000, duration = 6000, width = 854, height = 480,
    codedWidth = width, codedHeight = height, handler = 'vide', codec = 'avc1', avcC = avcConfiguration(),
    entryChildren = [], entries, tracks = 1, order = 'progressive', extraTop = [], extraMovie = []
}: ClipOptions = {}) => {
    const mvhd = box('mvhd', Buffer.alloc(4), u32(0), u32(0), u32(timescale), u32(duration), Buffer.alloc(80));
    const header = Buffer.alloc(84);
    header.writeUInt32BE(3, 0);
    header.writeUInt32BE(Math.round(width * 65536), 76);
    header.writeUInt32BE(Math.round(height * 65536), 80);
    const hdlr = Buffer.alloc(24);
    hdlr.write(handler, 8, 'latin1');
    const entry = sampleEntry(codec, codedWidth, codedHeight, ...(avcC ? [box('avcC', avcC)] : []), ...entryChildren);
    const stsd = Buffer.concat([Buffer.alloc(4), u32(1), entries ?? entry]);
    const trak = box('trak', box('tkhd', header), box('mdia', box('hdlr', hdlr), box('minf', box('stbl', box('stsd', stsd)))));
    const moov = box('moov', mvhd, ...Array.from({ length: tracks }, () => trak), ...extraMovie);
    const mdat = box('mdat', Buffer.alloc(32, 1));
    const ftyp = box('ftyp', Buffer.from(brand, 'latin1'), u32(512), Buffer.from('isomavc1', 'latin1'));
    return Buffer.concat(order === 'progressive' ? [ftyp, moov, mdat, ...extraTop] : [ftyp, mdat, moov, ...extraTop]);
};

test('the container walk accepts one progressive H.264 video track and reports its facts', () => {
    assert.deepEqual(inspectMotionPreviewContainer(clip()), { durationMs: 6000, width: 854, height: 480 });
    assert.deepEqual(inspectMotionPreviewContainer(clip({ width: 480, height: 854, codec: 'avc3' })), { durationMs: 6000, width: 480, height: 854 });
});

test('the sample entry accepts browser H.264 profiles, padding, non-square pixels, and ordinary sibling boxes', () => {
    const facts = { durationMs: 6000, width: 640, height: 360 };
    for (const profile of [66, 77, 100]) {
        assert.deepEqual(inspectMotionPreviewContainer(clip({ width: 640, height: 360, avcC: avcConfiguration({ profile }) })), facts, `profile ${profile}`);
    }
    // 360 rows are coded as 23 whole macroblocks; the reported facts stay the display size.
    assert.deepEqual(inspectMotionPreviewContainer(clip({ width: 640, height: 360, codedHeight: 368 })), facts);
    // FFmpeg scaling 1920 × 1080 to 854 × 480 writes a 1280:1281 sample aspect, so tkhd says 853.33.
    assert.deepEqual(inspectMotionPreviewContainer(clip({ width: 854 * 1280 / 1281, height: 480, codedWidth: 854 })),
        { durationMs: 6000, width: 853, height: 480 });
    // Non-square pixels: the display size differs from the coded size, and both stay within bounds.
    assert.deepEqual(inspectMotionPreviewContainer(clip({ width: 721.78, height: 406, codedWidth: 720, codedHeight: 406 })),
        { durationMs: 6000, width: 722, height: 406 });
    assert.deepEqual(inspectMotionPreviewContainer(clip({ width: 853.33, height: 480, codedWidth: 720, codedHeight: 480 })),
        { durationMs: 6000, width: 853, height: 480 });
    assert.deepEqual(inspectMotionPreviewContainer(clip({ width: 480.375, height: 854, codedWidth: 480, codedHeight: 854 })),
        { durationMs: 6000, width: 480, height: 854 });
    assert.deepEqual(inspectMotionPreviewContainer(clip({ width: 640, height: 360, avcC: avcConfiguration({ highExtension: [1, 0, 0] }) })), facts);
    assert.deepEqual(inspectMotionPreviewContainer(clip({
        width: 640, height: 360,
        avcC: avcConfiguration({ lengthSizeMinusOne: 1, spsCount: 2 }),
        entryChildren: [box('pasp', u32(1), u32(1)), box('btrt', Buffer.alloc(12)), box('colr', Buffer.from('nclx'), Buffer.alloc(7))]
    })), facts);
});

test('the sample entry rejects a coded size or H.264 configuration a small track header could hide', () => {
    const valid = avcConfiguration();
    const rejected: Array<[string, Buffer]> = [
        ['4K coded behind an 854 × 480 tkhd', clip({ codedWidth: 3840, codedHeight: 2160 })],
        ['1080p coded behind an 854 × 480 tkhd', clip({ codedWidth: 1920, codedHeight: 1080 })],
        ['padding beyond the width maximum', clip({ codedWidth: 864 })],
        ['zero coded width', clip({ codedWidth: 0 })],
        ['zero coded height', clip({ codedHeight: 0 })],
        ['a portrait coded size taller than the maximum', clip({ width: 480, height: 854, codedWidth: 480, codedHeight: 864 })],
        ['High 10', clip({ avcC: avcConfiguration({ profile: 110 }) })],
        ['High 4:2:2', clip({ avcC: avcConfiguration({ profile: 122 }) })],
        ['High 4:4:4 Predictive', clip({ avcC: avcConfiguration({ profile: 244 }) })],
        ['Extended', clip({ avcC: avcConfiguration({ profile: 88 }) })],
        ['High record over a High 10 SPS', clip({ avcC: avcConfiguration({ profile: 100, spsProfile: 110 }) })],
        ['High record declaring 4:4:4 chroma', clip({ avcC: avcConfiguration({ highExtension: [3, 0, 0] }) })],
        ['High record declaring 10-bit samples', clip({ avcC: avcConfiguration({ highExtension: [1, 2, 2] }) })],
        ['tkhd wider than the maximum by more than rounding', clip({ width: 854.6, codedWidth: 854 })],
        ['Baseline record over a High SPS', clip({ avcC: avcConfiguration({ profile: 66, spsProfile: 100 }) })],
        ['a PPS in the SPS list', clip({ avcC: avcConfiguration({ spsHeader: 0x68 }) })],
        ['forbidden NAL bit', clip({ avcC: avcConfiguration({ spsHeader: 0xe7 }) })],
        ['configuration version 2', clip({ avcC: avcConfiguration({ version: 2 }) })],
        ['no SPS', clip({ avcC: avcConfiguration({ spsCount: 0 }) })],
        ['3-byte NAL lengths', clip({ avcC: avcConfiguration({ lengthSizeMinusOne: 2 }) })],
        ['avcC without the PPS count', clip({ avcC: valid.subarray(0, 6 + 2 + 6) })],
        ['avcC truncated inside the PPS', clip({ avcC: valid.subarray(0, valid.length - 1) })],
        ['avcC truncated inside the SPS', clip({ avcC: valid.subarray(0, 10) })],
        ['avcC truncated inside the SPS length', clip({ avcC: valid.subarray(0, 7) })],
        ['avcC header only', clip({ avcC: valid.subarray(0, 5) })],
        ['no avcC', clip({ avcC: null })],
        ['two avcC boxes', clip({ entryChildren: [box('avcC', valid)] })],
        ['a sample entry shorter than its fixed fields', clip({ entries: box('avc1', Buffer.alloc(40)) })],
        ['bytes after the one sample entry', clip({ entries: Buffer.concat([sampleEntry('avc1', 854, 480, box('avcC', valid)), Buffer.alloc(8)]) })],
        ['a sample entry overrunning stsd', clip({ entries: Buffer.concat([u32(4096), Buffer.from('avc1'), Buffer.alloc(78)]) })]
    ];
    for (const [label, data] of rejected) {
        assert.throws(() => inspectMotionPreviewContainer(data), InvalidMotionPreviewError, label);
    }
});

test('the container walk rejects every profile outside the bounded, muted, progressive clip', () => {
    const rejected: Array<[string, Buffer]> = [
        ['moov after mdat', clip({ order: 'moov-last' })],
        ['a sound track', clip({ handler: 'soun' })],
        ['two tracks', clip({ tracks: 2 })],
        ['HEVC', clip({ codec: 'hvc1' })],
        ['too long', clip({ duration: 8_600 })],
        ['720p', clip({ width: 1280, height: 720 })],
        ['zero size', clip({ width: 0 })],
        ['QuickTime brand', clip({ brand: 'qt  ' })],
        ['fragments', clip({ extraTop: [box('moof', Buffer.alloc(8))] })],
        ['movie extends', clip({ extraMovie: [box('mvex', Buffer.alloc(8))] })],
        ['truncation', clip().subarray(0, clip().length - 5)],
        ['no ftyp', clip().subarray(clip().readUInt32BE(0))]
    ];
    for (const [label, data] of rejected) {
        assert.throws(() => inspectMotionPreviewContainer(data), InvalidMotionPreviewError, label);
    }
});

test('file validation checks size, type, and exact bytes before decoding, and hashes the accepted clip', async () => {
    const data = clip();
    let decoded = 0;
    const decode = async () => { decoded += 1; };
    const accepted = await validateMotionPreviewFile(
        { size: data.length, mimetype: 'video/mp4', buffer: data } as Express.Multer.File,
        undefined,
        { decode }
    );
    assert.equal(accepted.byteLength, data.length);
    assert.match(accepted.sha256, /^[0-9a-f]{64}$/);
    assert.equal(decoded, 1);

    for (const file of [
        { size: 0, mimetype: 'video/mp4', buffer: Buffer.alloc(0) },
        { size: 5 * 1024 * 1024, mimetype: 'video/mp4', buffer: data },
        { size: data.length, mimetype: 'video/quicktime', buffer: data },
        { size: data.length + 1, mimetype: 'video/mp4', buffer: data }
    ]) {
        await assert.rejects(validateMotionPreviewFile(file as Express.Multer.File, undefined, { decode }), InvalidMotionPreviewError);
    }
    assert.equal(decoded, 1);
});

const ffmpeg = process.env.ROOM_AUDIO_FFMPEG_PATH || 'ffmpeg';
const ffmpegAvailable = spawnSync(ffmpeg, ['-hide_banner', '-version'], { stdio: 'ignore' }).status === 0;

test('a real H.264 clip decodes completely, and a corrupted one is rejected', {
    // CI installs FFmpeg; a developer machine without it skips only this decode check.
    skip: !ffmpegAvailable && !process.env.CI ? 'FFmpeg is not installed' : false
}, async () => {
    const directory = mkdtempSync(path.join(tmpdir(), 'archtree-motion-preview-test-'));
    try {
        const output = path.join(directory, 'preview.mp4');
        execFileSync(ffmpeg, [
            '-hide_banner', '-loglevel', 'error', '-f', 'lavfi', '-i', 'testsrc=size=320x180:rate=24:duration=3',
            '-c:v', 'libx264', '-preset', 'ultrafast', '-pix_fmt', 'yuv420p', '-an', '-movflags', '+faststart', '-y', output
        ], { stdio: 'inherit' });
        const size = statSync(output).size;
        const accepted = await validateMotionPreviewFile({ path: output, size, mimetype: 'video/mp4' } as Express.Multer.File);
        assert.equal(accepted.width, 320);
        assert.equal(accepted.height, 180);
        assert.ok(Math.abs(accepted.durationMs - 3000) <= 100);

        const corrupted = Buffer.from(readFileSync(output));
        corrupted.fill(0, corrupted.length - Math.floor(size / 3));
        const brokenPath = path.join(directory, 'broken.mp4');
        writeFileSync(brokenPath, corrupted);
        await assert.rejects(
            validateMotionPreviewFile({ path: brokenPath, size: corrupted.length, mimetype: 'video/mp4' } as Express.Multer.File),
            (error: unknown) => error instanceof UndecodableMotionPreviewError || error instanceof InvalidMotionPreviewError
        );
    } finally {
        rmSync(directory, { recursive: true, force: true });
    }
});

/**
 * Overwrites a box's size fields found by its type, so a real file can lie about its frame size. The
 * search starts at `after` because `avc1` also appears as a compatible brand in ftyp.
 */
const patchBoxSize = (
    data: Buffer, type: string, offset: number, width: number, height: number, bytes: 2 | 4, after = 'moov'
) => {
    const at = data.indexOf(Buffer.from(type, 'latin1'), data.indexOf(Buffer.from(after, 'latin1')));
    assert.ok(at > 4, `${type} box present`);
    const start = at + 4 + offset;
    if (bytes === 2) {
        data.writeUInt16BE(width, start);
        data.writeUInt16BE(height, start + 2);
    } else {
        data.writeUInt32BE(width * 65536, start);
        data.writeUInt32BE(height * 65536, start + 4);
    }
};

test('real High-profile clips at the size limit decode, and a larger stream behind small headers does not', {
    skip: !ffmpegAvailable && !process.env.CI ? 'FFmpeg is not installed' : false
}, async () => {
    const directory = mkdtempSync(path.join(tmpdir(), 'archtree-motion-preview-limit-'));
    const encode = (name: string, size: string) => {
        const output = path.join(directory, name);
        execFileSync(ffmpeg, [
            '-hide_banner', '-loglevel', 'error', '-f', 'lavfi', '-i', `testsrc=size=${size}:rate=24:duration=2`,
            '-vf', 'setsar=1', '-c:v', 'libx264', '-profile:v', 'high', '-pix_fmt', 'yuv420p',
            '-an', '-movflags', '+faststart', '-y', output
        ], { stdio: 'inherit' });
        return output;
    };
    const validate = (file: string) => validateMotionPreviewFile({
        path: file, size: statSync(file).size, mimetype: 'video/mp4'
    } as Express.Multer.File);
    try {
        for (const [name, size, width, height] of [
            ['landscape.mp4', '854x480', 854, 480],
            ['portrait.mp4', '480x854', 480, 854]
        ] as const) {
            const accepted = await validate(encode(name, size));
            assert.equal(accepted.width, width, name);
            assert.equal(accepted.height, height, name);
        }

        // Both container sizes claim 854 × 480, but the stream decodes 1280 × 720 frames.
        const disguised = Buffer.from(readFileSync(encode('disguised.mp4', '1280x720')));
        patchBoxSize(disguised, 'tkhd', 76, 854, 480, 4);
        patchBoxSize(disguised, 'avc1', 24, 854, 480, 2, 'stsd');
        const disguisedPath = path.join(directory, 'disguised-patched.mp4');
        writeFileSync(disguisedPath, disguised);
        await assert.rejects(validate(disguisedPath), UndecodableMotionPreviewError);
    } finally {
        rmSync(directory, { recursive: true, force: true });
    }
});
